-- ComplyOS SaaS expansion migration. Applied to the dedicated ComplyOS Supabase project.
create table if not exists public.organization_settings (organization_id uuid primary key references public.organizations(id) on delete cascade, notification_preferences jsonb not null default '{}'::jsonb, default_reminder_days integer not null default 30, document_retention_policy jsonb not null default '{}'::jsonb, timezone text not null default 'Asia/Kolkata', date_format text not null default 'dd/MM/yyyy', language text not null default 'en', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.permissions (id uuid primary key default gen_random_uuid(), key text unique not null, description text, created_at timestamptz not null default now());
create table if not exists public.roles (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete cascade, name text not null, description text, is_system_role boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.role_permissions (role_id uuid not null references public.roles(id) on delete cascade, permission_id uuid not null references public.permissions(id) on delete cascade, primary key(role_id,permission_id));
create table if not exists public.vendor_contacts (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id) on delete cascade, name text not null, email text, phone text, designation text, created_at timestamptz not null default now());
create table if not exists public.obligation_evidence (id uuid primary key default gen_random_uuid(), obligation_id uuid not null references public.compliance_obligations(id) on delete cascade, document_id uuid not null references public.documents(id) on delete cascade, uploaded_by uuid, verification_status text not null default 'PENDING', verified_by uuid, verified_at timestamptz, notes text, created_at timestamptz not null default now(), unique(obligation_id,document_id));
create table if not exists public.task_comments (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, author_id uuid, comment text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.task_attachments (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, document_id uuid not null references public.documents(id) on delete cascade, uploaded_by uuid, created_at timestamptz not null default now(), unique(task_id,document_id));
create table if not exists public.ai_conversations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid, title text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ai_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.ai_conversations(id) on delete cascade, role text not null, content text not null, model text, provider text, prompt_version text, token_usage jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.ai_citations (id uuid primary key default gen_random_uuid(), message_id uuid not null references public.ai_messages(id) on delete cascade, document_id uuid references public.documents(id) on delete set null, document_version_id uuid references public.document_versions(id) on delete set null, page_number integer, source_text text, relevance numeric, created_at timestamptz not null default now());
create table if not exists public.reports (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, report_type text not null, name text not null, filters jsonb not null default '{}'::jsonb, generated_by uuid, generated_at timestamptz, status text not null default 'QUEUED', storage_path text, created_at timestamptz not null default now());
create table if not exists public.integrations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, provider text not null, status text not null default 'DISCONNECTED', encrypted_credentials text, scopes jsonb not null default '[]'::jsonb, connected_by uuid, connected_at timestamptz, last_sync_at timestamptz, error_state text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,provider));
create table if not exists public.webhooks (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, endpoint_url text not null, secret text not null, events jsonb not null default '[]'::jsonb, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.automation_rules (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, trigger_type text not null, trigger_config jsonb not null default '{}'::jsonb, action_type text not null, action_config jsonb not null default '{}'::jsonb, active boolean not null default true, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.feature_flags (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete cascade, key text not null, enabled boolean not null default false, config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,key));
create index if not exists idx_ai_conversations_org on public.ai_conversations(organization_id,updated_at desc);
create index if not exists idx_ai_messages_conversation on public.ai_messages(conversation_id,created_at);
create index if not exists idx_reports_org on public.reports(organization_id,created_at desc);
create index if not exists idx_integrations_org on public.integrations(organization_id,provider);
create index if not exists idx_automation_rules_org on public.automation_rules(organization_id,active);
create index if not exists idx_vendor_contacts_vendor on public.vendor_contacts(vendor_id);
create index if not exists idx_evidence_obligation on public.obligation_evidence(obligation_id);
create index if not exists idx_task_comments_task on public.task_comments(task_id,created_at);
alter table public.organization_settings enable row level security;
alter table public.roles enable row level security;
alter table public.role_permissions enable row level security;
alter table public.vendor_contacts enable row level security;
alter table public.obligation_evidence enable row level security;
alter table public.task_comments enable row level security;
alter table public.task_attachments enable row level security;
alter table public.ai_conversations enable row level security;
alter table public.ai_messages enable row level security;
alter table public.ai_citations enable row level security;
alter table public.reports enable row level security;
alter table public.integrations enable row level security;
alter table public.webhooks enable row level security;
alter table public.automation_rules enable row level security;
alter table public.feature_flags enable row level security;
create policy organization_settings_access on public.organization_settings for all using (is_org_member(organization_id)) with check (is_org_member(organization_id));
create policy roles_access on public.roles for all using (organization_id is null or is_org_member(organization_id)) with check (organization_id is null or is_org_member(organization_id));
create policy role_permissions_access on public.role_permissions for all using (exists(select 1 from public.roles r where r.id=role_id and (r.organization_id is null or is_org_member(r.organization_id)))) with check (exists(select 1 from public.roles r where r.id=role_id and (r.organization_id is null or is_org_member(r.organization_id))));
create policy vendor_contacts_access on public.vendor_contacts for all using (exists(select 1 from public.vendors v where v.id=vendor_id and is_org_member(v.organization_id))) with check (exists(select 1 from public.vendors v where v.id=vendor_id and is_org_member(v.organization_id)));
create policy obligation_evidence_access on public.obligation_evidence for all using (exists(select 1 from public.compliance_obligations o where o.id=obligation_id and is_org_member(o.organization_id))) with check (exists(select 1 from public.compliance_obligations o where o.id=obligation_id and is_org_member(o.organization_id)));
create policy task_comments_access on public.task_comments for all using (exists(select 1 from public.tasks t where t.id=task_id and is_org_member(t.organization_id))) with check (exists(select 1 from public.tasks t where t.id=task_id and is_org_member(t.organization_id)));
create policy task_attachments_access on public.task_attachments for all using (exists(select 1 from public.tasks t join public.documents d on d.id=document_id where t.id=task_id and is_org_member(t.organization_id) and d.organization_id=t.organization_id)) with check (exists(select 1 from public.tasks t join public.documents d on d.id=document_id where t.id=task_id and is_org_member(t.organization_id) and d.organization_id=t.organization_id));
create policy ai_conversations_access on public.ai_conversations for all using (is_org_member(organization_id)) with check (is_org_member(organization_id));
create policy ai_messages_access on public.ai_messages for all using (exists(select 1 from public.ai_conversations c where c.id=conversation_id and is_org_member(c.organization_id))) with check (exists(select 1 from public.ai_conversations c where c.id=conversation_id and is_org_member(c.organization_id)));
create policy ai_citations_access on public.ai_citations for all using (exists(select 1 from public.ai_messages m join public.ai_conversations c on c.id=m.conversation_id where m.id=message_id and is_org_member(c.organization_id))) with check (exists(select 1 from public.ai_messages m join public.ai_conversations c on c.id=m.conversation_id where m.id=message_id and is_org_member(c.organization_id)));
create policy reports_access on public.reports for all using (is_org_member(organization_id)) with check (is_org_member(organization_id));
create policy integrations_access on public.integrations for all using (is_org_member(organization_id)) with check (is_org_member(organization_id));
create policy webhooks_access on public.webhooks for all using (is_org_member(organization_id)) with check (is_org_member(organization_id));
create policy automation_rules_access on public.automation_rules for all using (is_org_member(organization_id)) with check (is_org_member(organization_id));
create policy feature_flags_access on public.feature_flags for all using (organization_id is null or is_org_member(organization_id)) with check (organization_id is null or is_org_member(organization_id));
insert into public.permissions(key,description) values ('organization.read','Read organization'),('organization.update','Update organization'),('members.read','Read members'),('members.invite','Invite members'),('members.update','Update members'),('members.remove','Remove members'),('documents.read','Read documents'),('documents.upload','Upload documents'),('documents.update','Update documents'),('documents.delete','Archive documents'),('documents.verify','Verify documents'),('compliance.read','Read compliance'),('compliance.create','Create compliance'),('compliance.update','Update compliance'),('tasks.read','Read tasks'),('tasks.create','Create tasks'),('tasks.update','Update tasks'),('tasks.assign','Assign tasks'),('risks.read','Read risks'),('risks.resolve','Resolve risks'),('vendors.read','Read vendors'),('vendors.create','Create vendors'),('vendors.update','Update vendors'),('reports.read','Read reports'),('reports.generate','Generate reports'),('audit.read','Read audit'),('settings.read','Read settings'),('settings.update','Update settings') on conflict(key) do nothing;
